T["Everyone from the chosen rank up (rank 1 = guild master) sees this hub and may change modules and announcements for the guild. Only the guild master sets the limit."] = "Wszyscy od wybranej rangi w górę (ranga 1 = mistrz gildii) widzą to centrum i mogą zmieniać moduły i ogłoszenia gildii. Granicę ustala tylko mistrz gildii."
T["Everyone up to the chosen rank (rank 1 = Guild Master) sees this hub and may change modules, appearance and announcements for the guild. Only the Guild Master sets the limit."] = "Wszyscy od wybranej rangi w górę (ranga 1 = mistrz gildii) widzą to centrum i mogą zmieniać moduły, wygląd i ogłoszenia gildii. Granicę ustala tylko mistrz gildii."
