T["All: Burning Adrenaline: run out of the raid AT ONCE (you are about to die).\nAll: Full resources at the start - use everything.\nTank: Set a tank order (Adrenaline on the tank).\nDD: Not in front of or behind the dragon."] = "All: Burning Adrenaline: NATYCHMIAST wybiegnij z rajdu (zaraz zginiesz).\nAll: Pełne zasoby na starcie - użyj wszystkiego.\nTank: Ustalcie kolejność tanków (Adrenaline na tanku).\nDD: Nie stój przed smokiem ani za nim."
T["All: Do not let the 8 Firesworn die near the raid (explosion).\nTank: Each add tank pulls their Firesworn away, warlocks banish.\nHealer: Dispel, keep an eye on the add tanks.\nDD: Garr first, adds only when called."] = "All: Nie pozwólcie, by 8 Firesworn zginęło blisko rajdu (eksplozja).\nTank: Każdy tank addów odciąga swojego Firesworn, warlocki banishują.\nHealer: Dispel, pilnuj tanków addów.\nDD: Najpierw Garr, addy tylko na komendę."
T["All: Tank the two Core Ragers away from the boss, do not kill them.\nTank: Swap the Golemagg tank when Magma Splash stacks too high.\nDD: Only on Golemagg."] = "All: Dwa Core Ragery tankować z dala od bossa, nie zabijać.\nTank: Zmiana tanka Golemagga, gdy Magma Splash ma za dużo stacków.\nDD: Tylko Golemagg."
T["All: The 4 priests first, they heal each other.\nTank: Keep Sulfuron and the priests apart.\nDD: Interrupt! Stop the priests' Dark Mending."] = "All: Najpierw 4 priestów, leczą się nawzajem.\nTank: Trzymaj Sulfurona i priestów osobno.\nDD: Przerywać! Zatrzymać Dark Mending priestów."
T["All: Fire protection! Wrath of Ragnaros knocks melee back - then get back in.\nAll: Sons phase (after 3 min or when he submerges): kill all Sons of Flame.\nTank: Second tank ready when the first is knocked away.\nHealer: Spread out, ranged not too close (Lava Burst).\nDD: Melee: keep mana under control, ranged keep your distance."] = "All: Ochrona przed ogniem! Wrath of Ragnaros odrzuca melee - potem wracaj.\nAll: Faza synów (po 3 min lub gdy się zanurzy): zabić wszystkich Sons of Flame.\nTank: Drugi tank gotowy, gdy pierwszy zostanie odrzucony.\nHealer: Rozstawieni, ranged nie za blisko (Lava Burst).\nDD: Melee: pilnuj many, ranged trzymaj dystans."
T["All: Flame Buffet stacks - ranged behind pillars to let it drop.\nTank: Two tanks behind pillars, Wing Buffet knocks back.\nDD: Onyxia Scale Cloak required."] = "All: Flame Buffet się stackuje - ranged za filary, żeby zszedł.\nTank: Dwóch tanków za filarami, Wing Buffet odrzuca.\nDD: Onyxia Scale Cloak obowiązkowy."
T["All: Remove Gehennas' Curse (reduced healing) at once.\nAll: Get out of the Rain of Fire.\nTank: Tank the two Flamewakers apart.\nDD: Flamewakers first, then Gehennas."] = "All: Natychmiast zdejmij Gehennas' Curse (słabsze leczenie).\nAll: Wyjdź z Rain of Fire.\nTank: Dwa Flamewakery tankować osobno.\nDD: Najpierw Flamewakery, potem Gehennas."
T["All: Remove Lucifron's Curse and Impending Doom at once (mages/druids, priests/paladins).\nTank: Tank the two guards apart - mind control!\nHealer: Spread out, dispel mind-controlled players.\nDD: Guards first, then Lucifron."] = "All: Natychmiast zdejmij Lucifron's Curse i Impending Doom (magowie/druidzi, priesti/paladyni).\nTank: Dwóch strażników tankować osobno - mind control!\nHealer: Stójcie rozstawieni, dispel na graczach pod mind control.\nDD: Najpierw strażnicy, potem Lucifron."
T["All: Living Bomb: run out of the raid AT ONCE!\nAll: Inferno - away from the boss, dispel Ignite Mana.\nTank: Hold the middle, step out briefly on Inferno.\nDD: Melee back off on Inferno."] = "All: Living Bomb: NATYCHMIAST wybiegnij z rajdu!\nAll: Inferno - z dala od bossa, dispel Ignite Mana.\nTank: Trzymaj środek, przy Inferno wyjdź na chwilę.\nDD: Melee odsuwa się przy Inferno."
T["All: Watch the guards' magic reflection/damage shield - stop damage then.\nTank: One guard per tank, mages sheep the elite guards.\nDD: Healer guards (Flamewaker Healer) first."] = "All: Uważaj na odbicie magii/tarczę obrażeń strażników - wtedy przerwij obrażenia.\nTank: Jeden strażnik na tanka, magowie owcują elitarnych strażników.\nDD: Najpierw strażnicy-healerzy (Flamewaker Healer)."
T["All: Never stand in front of or behind Onyxia (breath and tail sweep).\nAll: Phase 2 (65%): dodge fireballs, stay out of the cave entrances.\nAll: Phase 3 (40%): fear - Fear Ward/Tremor Totem ready, avoid the lava cracks.\nTank: Onyxia sideways at the wall, head away from the raid.\nTank: Phase 2: pick up the whelps. Phase 3: get aggro back at once.\nHealer: Tank has priority, spread out in phase 2.\nDD: Wait for 3 attacks of the tank. Phase 2: whelps first."] = "All: Nigdy nie stój przed Onyxią ani za nią (oddech i uderzenie ogonem).\nAll: Faza 2 (65%): unikaj kul ognia, nie wchodź do wejść jaskiń.\nAll: Faza 3 (40%): fear - Fear Ward/Tremor Totem w gotowości, omijaj szczeliny lawy.\nTank: Onyxia bokiem przy ścianie, głowa z dala od rajdu.\nTank: Faza 2: zbierz whelpy. Faza 3: natychmiast odzyskaj aggro.\nHealer: Tank ma priorytet, w fazie 2 stójcie rozstawieni.\nDD: Poczekaj na 3 ataki tanka. Faza 2: najpierw whelpy."
T["All: Never stand in front of or behind Onyxia (breath/tail).\nPhase 2 from 65%: dodge fireballs, kill whelps at once.\nPhase 3 from 40%: fear - grounding totem and fear ward ready.\nTank: Onyxia with her back to the wall, head away from the raid.\nTank: phase 3 take aggro back at once.\nHealer: tank first, spread out in phase 2.\nDPS: go full only after 3 sunders from the tank.\nDPS: phase 2: whelps before Onyxia."] = "All: Nigdy nie stój przed Onyxią ani za nią (oddech/ogon).\nPhase 2 from 65%: unikaj kul ognia, whelpy zabijać od razu.\nPhase 3 from 40%: fear - Grounding Totem i Fear Ward w gotowości.\nTank: Onyxia tyłem do ściany, głowa z dala od rajdu.\nTank: w fazie 3 natychmiast odzyskaj aggro.\nHealer: najpierw tank, w fazie 2 stójcie rozstawieni.\nDPS: pełne obrażenia dopiero po 3 Sunderach tanka.\nDPS: faza 2: whelpy przed Onyxią."
T["All: Panic - Fear Ward/Tremor Totem, hunters: Tranquilizing Shot on Frenzy.\nAll: Get out of the lava fire on the ground.\nTank: Magmadar with his back to the raid.\nDD: Ranged spread out at the back."] = "All: Panic - Fear Ward/Tremor Totem, hunterzy: Tranquilizing Shot na Frenzy.\nAll: Wyjdź z ognia lawy na ziemi.\nTank: Magmadar tyłem do rajdu.\nDD: Ranged rozstawieni z tyłu."
T["All: Phase 1: dragonkin from both sides, watch the class calls.\nAll: Phase 3 (20%): the skeletons rise again - kill them again.\nTank: Nefarian at the wall, fear - Fear Ward.\nHealer: Class call for priests: healing hurts - be careful.\nDD: Hunters/warriors: watch the class calls (weapons gone, stance)."] = "All: Faza 1: dragonkiny z obu stron, uważaj na class calle.\nAll: Faza 3 (20%): szkielety wstają ponownie - zabić jeszcze raz.\nTank: Nefarian przy ścianie, fear - Fear Ward.\nHealer: Class call na priestów: leczenie rani - uważaj.\nDD: Hunterzy/warriorzy: uważaj na class calle (brak broni, postawa)."
T["All: Phase 1: destroy the eggs (mind control via the orb), pick up the adds.\nAll: After all eggs: boss in the room - Fire Nova.\nTank: Gather the adds at the stairs.\nDD: Mages and dragonkin first."] = "All: Faza 1: niszczyć jaja (mind control przez kulę), przejmować addy.\nAll: Po wszystkich jajach: boss w sali - Fire Nova.\nTank: Zbierz addy przy schodach.\nDD: Najpierw magowie i dragonkiny."
T["All: Frenzy - hunters: Tranquilizing Shot.\nTank: Two tanks, watch Wing Buffet.\nDD: Onyxia Scale Cloak required."] = "All: Frenzy - hunterzy: Tranquilizing Shot.\nTank: Dwóch tanków, uwaga na Wing Buffet.\nDD: Onyxia Scale Cloak obowiązkowy."
T["All: Shadow of Ebonroc heals the boss - the tank with the debuff swaps.\nTank: Two tanks swap on Shadow.\nDD: Onyxia Scale Cloak required."] = "All: Shadow of Ebonroc leczy bossa - tank z debuffem się zmienia.\nTank: Dwóch tanków zmienia się przy Shadow.\nDD: Onyxia Scale Cloak obowiązkowy."
T["All: swarm target: run out.\nTank: infernal tank off to the side.\nHealer: remove sleep where possible.\nDPS: ignore infernals, everything on the boss."] = "All: cel roju: wybiegnij.\nTank: tank infernali na uboczu.\nHealer: zdejmuj sen, gdzie się da.\nDPS: ignoruj infernale, wszystko w bossa."
T["All: Knockback - stand against the wall.\nTank: Two tanks, aggro is split by Knock Away.\nDD: Mortal Strike on the tank: healers be prepared."] = "All: Knockback - stań przy ścianie.\nTank: Dwóch tanków, Knock Away dzieli aggro.\nDD: Mortal Strike na tanku: healerzy w gotowości."
T["All: He teleports - whoever has aggro, do not run away.\nAll: Remove Shazzrah's Curse, Arcane Explosion: melee keep your distance.\nTank: Get back on him right after every blink.\nHealer: Dispel (Deaden Magic)."] = "All: Teleportuje się - kto ma aggro, niech nie ucieka.\nAll: Zdejmij Shazzrah's Curse, Arcane Explosion: melee trzyma dystans.\nTank: Po każdym blinku od razu wracaj do niego.\nHealer: Dispel (Deaden Magic)."
T["All: leave Death and Decay at once.\nTank: hold the middle, don't move during frost nova.\nHealer: heal the ice block target fast.\nDPS: ranged spread wide (icebolt chain)."] = "All: natychmiast wyjdź z Death and Decay.\nTank: trzymaj środek, nie ruszaj się podczas Frost Nova.\nHealer: szybko wylecz cel Ice Blocka.\nDPS: ranged szeroko rozstawieni (łańcuch Iceboltów)."
T["All: Two of the five breath types per week - avoid the breath behind the corner.\nAll: Hourglass Sand for the Bronze affliction.\nTank: Tank at the gate, raid behind the corner.\nDD: Tranquilizing Shot on Frenzy."] = "All: Dwa z pięciu rodzajów oddechu na tydzień - oddechu unikasz za rogiem.\nAll: Hourglass Sand na Bronze affliction.\nTank: Tankuj przy bramie, rajd za rogiem.\nDD: Tranquilizing Shot na Frenzy."
