T["The guild leadership names raid leaders under Crown > Modules > Raids & Loot. In a running raid, the raid leader counts too."] = "Władze gildii wyznaczają liderów rajdu w Korona > Moduły > Rajdy & łup. W trwającym rajdzie liczy się też lider rajdu."
