T["Who sends data that others reject (no permission, forged author, made-up entries). An unmodified Oasis practically never does this - a hint, not proof."] = "Kto wysyła dane odrzucane przez innych (brak uprawnień, sfałszowany autor, zmyślone wpisy). Niezmodyfikowane Oasis praktycznie nigdy tego nie robi - to wskazówka, nie dowód."
T["Anyone who registers interest appears in a matching slot. Once there is an event, sign up directly on its card."] = "Kto zgłosi zainteresowanie, pojawi się tu na pasującym miejscu. Gdy jest wydarzenie, zapisujesz się bezpośrednio na karcie."
T["Whoever already received an item on need that evening drops behind everyone without an item on need (same roll rank)."] = "Kto danego wieczoru dostał już przedmiot na need, przy need spada za wszystkich bez przedmiotu (ta sama ranga rzutu)."
