T["Who sees the crown at the top. Without rights it is grey and only opens a preview."] = "Kto widzi koronę u góry. Bez uprawnień jest szara i otwiera tylko podgląd."
T["Whoever reserved an item for the event comes before everyone else on need."] = "Kto zarezerwował przedmiot na wydarzenie, ma przy need pierwszeństwo przed wszystkimi."
T["Who may pin a message at the top of guild chat"] = "Kto może przypiąć wiadomość na górze czatu gildii"
T["Who can invite is not known yet - log in once with your main and Oasis will remember the guild leadership."] = "Nie wiadomo jeszcze, kto może zapraszać - zaloguj się raz mainem, a Oasis zapamięta władze gildii."
