T["Whoever shows up often and has received little gets first pick on 'Need'. Part of the points decays every week."] = "Kto często bierze udział, a mało dostał, ma pierwszeństwo przy 'Need'. Co tydzień część punktów przepada."
T["Anyone who signs up with a fitting role is invited to your group right away."] = "Kto zgłosi się z pasującą rolą, od razu dostaje zaproszenie do Twojej grupy."
T["Who sees Guild Leadership?"] = "Kto widzi Władze gildii?"
T["Who stands where with which faction? Close to the goal, farm together, progress this week"] = "Kto jak stoi u której frakcji? Tuż przed celem, wspólne farmienie, postęp w tym tygodniu"
T["Who dies the most, to what and where – the guild's death ranking"] = "Kto ginie najczęściej, od czego i gdzie - gildyjny ranking śmierci"
T["Who deals, heals and takes the most?"] = "Kto zadaje, leczy i przyjmuje najwięcej?"
T["Who has been offline for long - clean up with one click."] = "Kto dawno nie był online - posprzątaj jednym kliknięciem."
T["The guild master decides who belongs to the leadership under Crown > Guild."] = "Kto należy do władz, ustala mistrz gildii w Korona > Gildia."
T["Tools"] = "Narzędzia"
T["Stats"] = "Statystyki"
T["stats do nothing for your role"] = "statystyki nic nie dają Twojej roli"
T["stats for info only"] = "statystyki tylko informacyjnie"
T["Stats, yearbook, daily goal, records and adventures of your character."] = "Statystyki, rocznik, cel dnia, rekordy i przygody Twojej postaci."
T["Stats: +healing, intellect, spirit, mp5;Weapon: staff or one-hander + off-hand with healing;Healing: Rejuvenation and Regrowth ahead, Healing Touch for big hits;Tip: Innervate for mana, Rebirth for fallen healers"] = "Statystyki: +leczenie, intelekt, duch, mp5;Broń: kostur lub jednoręczna + off-hand z leczeniem;Leczenie: Rejuvenation i Regrowth z wyprzedzeniem, Healing Touch na duże trafienia;Wskazówka: Innervate na manę, Rebirth dla poległych healerów"
T["Stats: +healing, intellect, spell crit (Illumination refunds mana), mp5;Weapon: one-hander + off-hand/shield with healing;Healing: Flash of Light for small damage, Holy Light (low rank) for big hits;Tip: hand out blessings, Divine Protection when you pull aggro"] = "Statystyki: +leczenie, intelekt, kryt zaklęć (Illumination zwraca manę), mp5;Broń: jednoręczna + off-hand/tarcza z leczeniem;Leczenie: Flash of Light na małe obrażenia, Holy Light (niska ranga) na duże trafienia;Wskazówka: rozdawaj blessingi, Divine Protection, gdy złapiesz aggro"
T["Stats: +healing, mp5, intellect - spirit does little;Weapon: one-hander + shield with healing;Healing: Chain Heal for groups, Healing Wave (low rank) for the tank;Tip: drop Mana Spring Totem, Earth Shield on the tank"] = "Statystyki: +leczenie, mp5, intelekt - duch daje niewiele;Broń: jednoręczna + tarcza z leczeniem;Leczenie: Chain Heal na grupy, Healing Wave (niska ranga) na tanka;Wskazówka: stawiaj Mana Spring Totem, Earth Shield na tanka"
T["Stats: +healing, spirit (Meditation: regen while casting), intellect, mp5;Weapon: staff or one-hander + off-hand with healing, wand;Healing: Renew and Power Word: Shield ahead, Greater Heal (low rank) for the tank;Tip: Prayer of Healing for the group, Fade on aggro"] = "Statystyki: +leczenie, duch (Meditation: regeneracja także podczas czarowania), intelekt, mp5;Broń: kostur lub jednoręczna + off-hand z leczeniem, różdżka;Leczenie: Renew i Power Word: Shield z wyprzedzeniem, Greater Heal (niska ranga) na tanka;Wskazówka: Prayer of Healing na grupę, Fade przy aggro"
T["Stats: armor (bear form multiplies it), stamina, agility (dodge + armor);Weapon: damage doesn't matter - only the stats (staff/polearm with stamina);Rotation: Maul, Swipe for packs, Demoralizing Roar;Tip: strength for more threat, Enrage to start"] = "Statystyki: pancerz (forma niedźwiedzia go mnoży), wytrzymałość, zręczność (unik + pancerz);Broń: obrażenia bez znaczenia - liczą się tylko statystyki (kostur/broń drzewcowa z wytrzymałością);Rotacja: Maul, Swipe na grupy, Demoralizing Roar;Wskazówka: siła na większy threat, Enrage na start"
T["Stats: strength (1 point = 2 AP), agility (AP + crit), crit, hit up to +9 %;Weapon: damage doesn't matter - only the stats;Rotation: Claw/Shred for combo points, then Ferocious Bite;Tip: powershift (recast form) for energy, open from stealth"] = "Statystyki: siła (1 punkt = 2 AP), zręczność (AP + kryt), kryt, trafienie do +9 %;Broń: obrażenia bez znaczenia - liczą się tylko statystyki;Rotacja: Claw/Shred na combo pointy, potem Ferocious Bite;Wskazówka: powershift (ponowna zmiana formy) dla energii, otwieraj ze stealtha"
T["Stats: strength (1 point = 2 AP), crit (procs Flurry = faster swings), hit up to +9 %;Weapon: slow two-hander - Windfury procs per swing, so slower = more damage;Rotation: Windfury Weapon, Stormstrike, Earth Shock;Tip: Strength of Earth and Windfury Totem for the group"] = "Statystyki: siła (1 punkt = 2 AP), kryt (wyzwala Flurry = szybsze ciosy), trafienie do +9 %;Broń: wolna dwuręczna - Windfury wyzwala się przy ciosie, więc im wolniejsza, tym więcej obrażeń;Rotacja: Windfury Weapon, Stormstrike, Earth Shock;Wskazówka: Strength of Earth Totem i Windfury Totem dla grupy"
T["Stats: strength (1 point = 2 AP), crit, hit up to +9 %;Weapon: slow two-hander - seals and Judgement scale per swing;Rotation: Seal of Righteousness/Command, Judgement, reapply seal;Tip: Consecration only with enough mana, Blessing of Might on yourself"] = "Statystyki: siła (1 punkt = 2 AP), kryt, trafienie do +9 %;Broń: wolna dwuręczna - seale i Judgement działają od ciosu;Rotacja: Seal of Righteousness/Command, Judgement, odnów seal;Wskazówka: Consecration tylko przy zapasie many, Blessing of Might na siebie"
T["Stats: hit up to +9 %, agility (1 AP, ~29 = 1 % crit), AP, crit;Weapon: Combat = fast off-hand, slow main hand (Sinister Strike); daggers for Backstab;Rotation: build combo points, keep Slice and Dice up, then Eviscerate;Tip: dual wielding misses white hits more often - hit matters most"] = "Statystyki: trafienie do +9 %, zręczność (1 AP, ok. 29 = 1 % kryta), AP, kryt;Broń: Combat = szybki off-hand, wolna główna ręka (Sinister Strike); sztylety do Backstab;Rotacja: buduj combo pointy, utrzymuj Slice and Dice, potem Eviscerate;Wskazówka: z dwiema broniami zwykłe ciosy częściej pudłują - trafienie jest najważniejsze"
T["Stats: hit up to +9 %, agility (2 ranged AP, ~53 = 1 % crit), AP, intellect;Weapon: slow ranged weapon (big damage per shot), melee weapon for stats;Rotation: Hunter's Mark, Auto Shot, Aimed Shot/Multi-Shot in between;Tip: feed your pet and keep it happy, Freezing Trap (square) for control"] = "Statystyki: trafienie do +9 %, zręczność (2 AP dystansowe, ok. 53 = 1 % kryta), AP, intelekt;Broń: wolna broń dystansowa (duże obrażenia na strzał), broń biała ze statystykami;Rotacja: Hunter's Mark, Auto Shot, między nimi Aimed Shot/Multi-Shot;Wskazówka: karm peta i dbaj o jego zadowolenie, Freezing Trap (kwadrat) do kontroli"
T["Stats: hit up to +9 %, strength (1 point = 2 AP), crit (~20 agility = 1 %);Weapon: slow two-hander (Mortal Strike, Heroic Strike scale per swing);Rotation: build rage, Mortal Strike / Bloodthirst, Whirlwind, spare rage into Heroic Strike;Tip: Battle Shout before the pull, Execute below 20 % health"] = "Statystyki: trafienie do +9 %, siła (1 punkt = 2 AP), kryt (ok. 20 zręczności = 1 %);Broń: wolna dwuręczna (Mortal Strike, Heroic Strike działają od ciosu);Rotacja: buduj rage, Mortal Strike / Bloodthirst, Whirlwind, nadmiar rage w Heroic Strike;Wskazówka: Battle Shout przed walką, Execute poniżej 20 % życia"
T["Stats: defense (440 = crit immune vs bosses at 60), stamina, armor, block;Weapon: one-hander + shield, fast weapon = more rage;Rotation: Shield Slam/Revenge, Sunder Armor on the target, Heroic Strike with high rage;Tip: hit helps so Taunt and abilities don't miss"] = "Statystyki: obrona (440 = odporność na kryty bossów na 60), wytrzymałość, pancerz, blok;Broń: jednoręczna + tarcza, szybka broń = więcej rage;Rotacja: Shield Slam/Revenge, Sunder Armor na cel, Heroic Strike przy dużym rage;Wskazówka: trafienie pomaga, by Taunt i umiejętności nie pudłowały"
T["Stats: defense, stamina, armor, then spell damage for more threat;Weapon: one-hander (ideally spell damage) + shield;Rotation: Righteous Fury on, Consecration for packs, keep Holy Shield up;Tip: mana is tight - use Seal of Wisdom or some intellect"] = "Statystyki: obrona, wytrzymałość, pancerz, potem obrażenia zaklęć na większy threat;Broń: jednoręczna (najlepiej z obrażeniami zaklęć) + tarcza;Rotacja: włącz Righteous Fury, Consecration na grupy, utrzymuj Holy Shield;Wskazówka: many jest mało - weź Seal of Wisdom albo trochę intelektu"
T["Stats: spell damage, spell crit (Elemental Focus saves mana), intellect, mp5;Weapon: one-hander + shield/off-hand with spell damage;Rotation: spam Lightning Bolt, Chain Lightning on packs, Flame Shock;Tip: spell hit up to +16 % in raids, Mana Spring Totem against oom"] = "Statystyki: obrażenia zaklęć, kryt zaklęć (Elemental Focus oszczędza manę), intelekt, mp5;Broń: jednoręczna + tarcza/off-hand z obrażeniami zaklęć;Rotacja: spamuj Lightning Bolt, Chain Lightning na grupy, Flame Shock;Wskazówka: trafienie zaklęć do +16 % w rajdzie, Mana Spring Totem na brak many"
T["Stats: spell damage, spell crit, intellect, spell hit up to +16 % in raids;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Moonfire + Insect Swarm, then Wrath or Starfire;Tip: Innervate yourself when mana runs low"] = "Statystyki: obrażenia zaklęć, kryt zaklęć, intelekt, trafienie zaklęć do +16 % w rajdzie;Broń: kostur lub jednoręczna + off-hand z obrażeniami zaklęć;Rotacja: Moonfire + Insect Swarm, potem Wrath lub Starfire;Wskazówka: Innervate na siebie, gdy kończy się mana"
T["Stats: spell damage, spell hit up to +16 % (raid), stamina, intellect;Weapon: staff or dagger + off-hand with spell damage, wand for leftover mana;Rotation: Corruption + curse, then Shadow Bolt; Life Tap instead of drinking;Tip: stamina pays off twice (Life Tap, Voidwalker/Soul Link)"] = "Statystyki: obrażenia zaklęć, trafienie zaklęć do +16 % (rajd), wytrzymałość, intelekt;Broń: kostur lub sztylet + off-hand z obrażeniami zaklęć, różdżka na resztki many;Rotacja: Corruption + klątwa, potem Shadow Bolt; Life Tap zamiast picia;Wskazówka: wytrzymałość opłaca się podwójnie (Life Tap, Voidwalker/Soul Link)"
T["Stats: spell damage, spell hit up to +16 % (raid), spirit for mana;Weapon: staff or one-hander + off-hand with spell damage;Rotation: Shadow Word: Pain, Mind Blast, Mind Flay;Tip: stay in Shadowform, Vampiric Embrace heals the group"] = "Statystyki: obrażenia zaklęć, trafienie zaklęć do +16 % (rajd), duch dla many;Broń: kostur lub jednoręczna + off-hand z obrażeniami zaklęć;Rotacja: Shadow Word: Pain, Mind Blast, Mind Flay;Wskazówka: stale w Shadowform, Vampiric Embrace leczy grupę"
T["Stats: spell damage, then spell hit up to +16 % (raid bosses), intellect, spell crit;Weapon: staff with spell damage, plus a wand for leftover mana;Rotation: spam Frostbolt or Fireball, Evocation when out of mana;Leveling: intellect and spirit = less downtime, sheep (moon) in groups"] = "Statystyki: obrażenia zaklęć, potem trafienie zaklęć do +16 % (bossowie rajdowi), intelekt, kryt zaklęć;Broń: kostur z obrażeniami zaklęć, do tego różdżka na resztki many;Rotacja: spamuj Frostbolt lub Fireball, Evocation przy braku many;Levelowanie: intelekt i duch = mniej przerw, w grupach owca (księżyc)"
