T["In a group WoW does not tell addons who landed a hit. Oasis only counts a critical hit if it directly follows your own attack and matches the damage meter after the fight. Marked as estimated in the ranking."] = "W grupie WoW nie mówi addonom, kto trafił. Oasis liczy trafienie krytyczne tylko wtedy, gdy następuje bezpośrednio po Twoim ataku i po walce zgadza się z licznikiem obrażeń. W rankingu oznaczone jako szacunkowe."
