T["Shows BETTER / WORSE / CAN'T EQUIP with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI is loaded with its own comparison, Oasis shows nothing (avoids doubles) - turn it off there with /nes vergleich."] = "Pokazuje LEPSZE / GORSZE / NIE DO ZAŁOŻENIA z efektem (DPS, życie, pancerz) i tabelą statystyk. Porównanie Blizzarda pojawia się wtedy tylko z Shiftem. Jeśli załadowano nesUI z własnym porównaniem, Oasis nic nie pokazuje (inaczej podwójnie) - wyłącz je tam przez /nes vergleich."
T["Shows better / worse / can't equip with effect (DPS, health, armor) and a stats table. Blizzard's comparison then only appears with Shift. If nesUI with its own comparison is loaded, Oasis shows nothing (otherwise doubled) - turn it off there with /nes vergleich."] = "Pokazuje lepsze / gorsze / nie do założenia z efektem (DPS, życie, pancerz) i tabelą statystyk. Porównanie Blizzarda pojawia się wtedy tylko z Shiftem. Jeśli załadowano nesUI z własnym porównaniem, Oasis nic nie pokazuje (inaczej podwójnie) - wyłącz je tam przez /nes vergleich."
T["Shows dungeon loot in your level range that beats your equipped item."] = "Pokazuje łup z lochów z Twojego zakresu poziomów, lepszy od założonego przedmiotu."
T["Shows Oasis messages in chat"] = "Pokazuje wiadomości Oasis na czacie"
T["Shows a gem from Oasis rank 30 and a shimmering name from rank 70 in the Oasis guild chat"] = "Od rangi Oasis 30 pokazuje klejnot, a od rangi 70 mieniące się imię na czacie gildii Oasis"
T["Now and then shows classic Barrens chat lines in General - Chuck Norris, Mankrik's wife ... Only for you, nothing is sent."] = "Co jakiś czas pokazuje klasyczne teksty z czatu Barrens na kanale General - Chuck Norris, żona Mankrika ... Tylko u Ciebie, nic nie jest wysyłane."
T["Now and then shows classic Barrens chat lines in General - Chuck Norris, Mankrik's wife ... Only for you, nothing is sent. Click: switch"] = "Co jakiś czas pokazuje klasyczne teksty z czatu Barrens na kanale General - Chuck Norris, żona Mankrika ... Tylko u Ciebie, nic nie jest wysyłane. Kliknij: przełącz"
T["Shows which materials green, blue and epic items can disenchant into"] = "Pokazuje, jakie materiały mogą wypaść z disenchantu zielonych, niebieskich i epickich przedmiotów"
T["Shows the level range of each zone"] = "Pokazuje zakres poziomów każdej strefy"
T["Shows you the crown and Guild Leadership like a Guild Master – only on your PC. The guild sees none of it."] = "Pokazuje Ci koronę i Władze gildii jak mistrzowi gildii - tylko na Twoim PC. Gildia nic z tego nie widzi."
T["Shows a notice as soon as a guildmate creates a new event"] = "Pokazuje powiadomienie, gdy ktoś z gildii utworzy nowe wydarzenie"
T["Shows typical Barrens chat lines in general chat now and then while in the Barrens - Chuck Norris, Mankrik's wife ... Only for you, nothing is sent."] = "W Barrens co jakiś czas pokazuje typowe teksty na czacie ogólnym - Chuck Norris, żona Mankrika ... Tylko u Ciebie, nic nie jest wysyłane."
T["Shows in the item tooltip who reserved the item for an upcoming event"] = "Pokazuje w tooltipie przedmiotu, kto zarezerwował go na nadchodzące wydarzenie"
T["Shows in the tooltip who in the guild can craft the item"] = "Pokazuje w tooltipie, kto w gildii może wytworzyć przedmiot"
T["Shows in the tooltip how many are in the guild bank"] = "Pokazuje w tooltipie, ile sztuk leży w banku gildii"
T["Shows in the listing that you talk by voice (Discord etc.). Joining is still handled by Blizzard / your group leader."] = "Pokazuje na liście, że rozmawiacie głosowo (Discord itp.). Dołączaniem nadal zarządza Blizzard / lider grupy."
T["Shows mains only. Alts are characters assigned to another main."] = "Pokazuje tylko mainy. Alty to postacie przypisane do innego maina."
T["Shows only the header with the number of builds."] = "Pokazuje tylko nagłówek z liczbą buildów."
T["Shows at a glance who in the guild has the same quests and is online right now - one click invites them."] = "Od razu pokazuje, kto z gildii ma te same zadania i jest teraz online - jedno kliknięcie go zaprasza."
